public class A39Oracle {
 public static Object publishOne(String typeName,String payload,String metric){
  SObject e=Schema.getGlobalDescribe().get(typeName).newSObject(null,false);
  e.put('Payload__c',payload);
  Database.SaveResult s=EventBus.publish(e);
  if(metric=='success') return s.isSuccess();
  if(metric=='id-null') return s.getId()==null;
  if(metric=='errors') return s.getErrors().size();
  if(metric=='id-type') return s.getId()==null?'null':s.getId().getSObjectType().getDescribe().getName();
  if(metric=='uuid-present') return e.get('EventUuid')!=null;
  if(metric=='replay-null') return e.get('ReplayId')==null;
  if(metric=='payload') return e.get('Payload__c');
  if(metric=='type') return e.getSObjectType().getDescribe().getName();
  if(metric=='result-type') {Object value=s; return value instanceof Database.SaveResult;}
  List<String> errors=new List<String>();
  for(Database.Error err:s.getErrors()) errors.add(String.valueOf(err.getStatusCode())+':'+err.getMessage()+':'+String.join(err.getFields(),','));
  return s.isSuccess()+'|'+s.getErrors().size()+'|'+String.join(errors,';');
 }
 public static Object publishSingle(SObject event){
  return EventBus.publish(event).isSuccess();
 }
 public static Object publishList(List<SObject> events,String metric){
  List<Database.SaveResult> results=EventBus.publish(events);
  if(metric=='count') return results.size();
  if(metric=='first') return results[0].isSuccess();
  List<String> statuses=new List<String>();
  for(Database.SaveResult result:results) statuses.add(String.valueOf(result.isSuccess()));
  return String.join(statuses,'|');
 }
 public static Object publishMany(String typeName,Integer n,String metric){
  Schema.SObjectType eventType=Schema.getGlobalDescribe().get(typeName);
  List<SObject> es=new List<SObject>();
  for(Integer i=0;i<n;i++){
   SObject e=eventType.newSObject(null,false);
   e.put('Payload__c','normal'); e.put('Ordinal__c',i); es.add(e);
  }
  List<Database.SaveResult> ss=EventBus.publish(es);
  if(metric=='count') return ss.size();
  Integer count=0;
  for(Database.SaveResult s:ss){
   if(metric=='success-count' && s.isSuccess()) count++;
   if(metric=='id-type-count' && s.getId()!=null && s.getId().getSObjectType()==eventType) count++;
  }
  return count;
 }
}

