public class A39Subscriber {
 public class CheckpointFailureException extends Exception {}
 public static void receive(List<SObject> events){
  // Immediate publishes may outlive anonymous transport rollback. No live
  // records or observable hosted delivery are created by this fixture.
  if(!Test.isRunningTest() || events.isEmpty()) return;
  EventBus.TriggerContext ctx=EventBus.TriggerContext.currentContext();
  String mode=(String)events[0].get('Mode__c');
  if(mode!=null && mode.startsWith('retry')){
   Integer maximum=Integer.valueOf(mode.substring(5));
   if(ctx.retries<maximum) throw new EventBus.RetryableException('A39-owned retry');
  }
  List<Account> observations=new List<Account>();
  if(mode=='checkpoint' || mode=='checkpoint-failure'){
   for(SObject e:events){
    if(mode=='checkpoint-failure' && ((Decimal)e.get('Ordinal__c'))==1 && ((Decimal)events[0].get('Ordinal__c'))==0)
     throw new CheckpointFailureException('A39-owned checkpoint failure');
    insert new Account(Name='A39-oracle-20261005',AccountNumber=mode,NumberOfEmployees=events.size(),
     Description=ctx.retries+'|'+(e.get('ReplayId')!=null)+'|'+(e.get('EventUuid')!=null),AnnualRevenue=(Decimal)e.get('Ordinal__c'));
    ctx.setResumeCheckpoint(String.valueOf(e.get('ReplayId')));
   }
  }else{
   // One observation per delivered batch avoids 2000 unrelated Account
   // trigger executions obscuring the event-batch observation with CPU limits.
   SObject e=events[0];
   observations.add(new Account(Name='A39-oracle-20261005',AccountNumber=mode,
    NumberOfEmployees=events.size(),Description=ctx.retries+'|'+Trigger.isExecuting+'|'+Trigger.isAfter+'|'+Trigger.isInsert+'|'+Trigger.size+'|'+(Trigger.old==null)+'|'+(e.get('ReplayId')!=null)+'|'+(e.get('EventUuid')!=null),
    AnnualRevenue=(Decimal)e.get('Ordinal__c')));
  }
  insert observations;
 }
}

